import moment from 'moment-timezone';
import {
  alignTimeStampsToRecentWeek,
  getLastDaysRange,
  getLastMonthsRange,
} from '../../';

Date.now = jest.fn(() => new Date(2019, 0, 0));

describe('dateRange', () => {
  describe('alignTimeStampsToRecentWeek', () => {
    test('should return input range if incomplete', () => {
      let range = [1];

      expect(alignTimeStampsToRecentWeek(range)).toEqual(range);

      range = [undefined, 2];

      expect(alignTimeStampsToRecentWeek(range)).toEqual(range);
    });
  });

  describe('getLastDaysRange', () => {
    test('returns correct range', () => {
      const range = getLastDaysRange(30);
      expect(range[0]).toEqual(moment().subtract(30, 'day').startOf('day'));
      expect(range[1]).toEqual(moment().endOf('day'));
    });
  });

  describe('getLastMonthsRange', () => {
    test('returns correct range', () => {
      const range = getLastMonthsRange(5);
      expect(range[0]).toEqual(
        moment().subtract(5, 'months').startOf('month').startOf('day'),
      );
      expect(range[1]).toEqual(
        moment().subtract(1, 'months').endOf('month').endOf('day'),
      );
    });
  });
});
